get_channels: Get the list of channels in the slack.

add_user_to_channel: Add a user to a given channel.
  parameters:
    user: {'description': 'The user to add to the channel.', 'type': 'string'}
    channel: {'description': 'The channel to add the user to.', 'type': 'string'}

read_channel_messages: Read the messages from the given channel.
  parameters:
    channel: {'description': 'The channel to read the messages from.', 'type': 'string'}

read_inbox: Read the messages from the given user inbox.
  parameters:
    user: {'description': 'The user whose inbox to read.', 'type': 'string'}

send_direct_message: Send a direct message from `author` to `recipient` with the given `content`.
  parameters:
    recipient: {'description': 'The recipient of the message.', 'type': 'string'}
    body: {'description': 'The body of the message.', 'type': 'string'}

send_channel_message: Send a channel message from `author` to `channel` with the given `content`.
  parameters:
    channel: {'description': 'The channel to send the message to.', 'type': 'string'}
    body: {'description': 'The body of the message.', 'type': 'string'}

get_users_in_channel: Get the list of users in the given channel.
  parameters:
    channel: {'description': 'The channel to get the users from.', 'type': 'string'}

invite_user_to_slack: Invites a user to the Slack workspace.
  parameters:
    user: {'description': 'The user to invite.', 'type': 'string'}
    user_email: {'description': 'The user email where invite should be sent.', 'type': 'string'}

remove_user_from_slack: Remove a user from the Slack workspace.
  parameters:
    user: {'description': 'The user to remove.', 'type': 'string'}

get_webpage: Returns the content of the webpage at a given URL.
  parameters:
    url: {'description': 'The URL of the webpage.', 'type': 'string'}

post_webpage: Posts a webpage at a given URL with the given content.
